//! Source-bound, nonrespondable clock conversion. All payment remains atomic.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
use serde::{Serialize,Deserialize};
use std::collections::BTreeSet;
pub(crate) const ID:&str="JZ42";pub(crate) const KEY:&str="jz42-clock-arrival";
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]
pub struct Draft{pub actor:usize,pub turn:u32,pub card:Card,pub society:Card}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]
pub struct Payment{pub before:u32,pub destroyed:Vec<String>,pub society:Card,pub removed:Vec<(Card,u32)>}
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
pub(crate) fn definition()->Definition{let mut a=ability(KEY,"末日钟降临：支付减免后费用并替换本方秘社（不可响应）",Timing::Standard,vec![],vec![],vec![Op::JZ42Convert],None);a.play_only=true;a.response_policy=ResponsePolicy::Immediate;with_abilities(vec![a])}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("jz42-")||a.ops.iter().any(|o|matches!(o,Op::JZ42Convert))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!same(a,&definition().abilities[0]){return Err("末日钟降临原不可响应程序损坏".into())}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("末日钟降临定义不能改写或移植".into())}Ok(())}
pub(crate) fn action(a:&Action)->RuleResult<()>{if *a!=(Action{card_id:a.card_id.clone(),ability_id:a.ability_id.clone(),cost_selected:a.cost_selected.clone(),..Action::new("play")})||a.ability_id.as_deref().is_some_and(|k|k!=KEY){return Err("末日钟降临只接受原牌和时间支付选择".into())}Ok(())}
impl Game{
 fn jz42_carriers(&self,actor:usize)->Vec<Card>{let mut cs=self.in_play_cards().into_iter().filter(|(_,c)|c.controller==actor&&c.time_markers>0).map(|(_,c)|c.clone()).collect::<Vec<_>>();if let Some(c)=self.players[actor].society_zone.card.as_ref().filter(|c|c.controller==actor&&c.time_markers>0){cs.push(c.clone());}cs}
 fn jz42_options(&self,actor:usize)->Vec<ChoiceOption>{self.jz42_carriers(actor).into_iter().flat_map(|c|(0..c.time_markers).map(move|i|ChoiceOption{id:format!("{}:{i}",c.id),label:format!("{} {} 时间{}",catalog::card(&c.definition).name,c.id,i+1),card:None})).collect()}
 fn jz42_draft(&self,d:&Draft)->RuleResult<()>{if d.actor>=self.players.len()||self.turn!=d.turn||self.status!="playing"||self.players[d.actor].eliminated||d.card.definition!=ID||d.card.controller!=d.actor||d.card.face_down||self.players[d.actor].hand.iter().find(|c|c.id==d.card.id).is_none_or(|c|!same(c,&d.card))||self.players[d.actor].society_zone.card.as_ref().is_none_or(|c|!same(c,&d.society))||d.society.controller!=d.actor||d.society.face_down||!self.loyalty(d.actor,ID)||self.resources(d.actor)<self.effective_cost(d.actor,&d.card).saturating_sub(self.jz42_options(d.actor).len()as u32){return Err("末日钟费用选择原手牌、秘社或支付资格已变化".into())}if self.window!=Some(Window::Action(self.team(d.actor)))||self.priority_team!=self.team(d.actor)||!self.stack.is_empty(){return Err("末日钟须在原本方标准行动窗口支付".into())}self.msjz03_allow_play(d.actor,&d.card)}
 pub(crate) fn jz42_begin(&mut self,actor:usize,c:&Card,a:&Action)->RuleResult<()>{action(a)?;let d=Draft{actor,turn:self.turn,card:c.clone(),society:self.players[actor].society_zone.card.clone().ok_or("须有可替换的本方秘社")?};self.jz42_draft(&d)?;let opts=self.jz42_options(actor);let max=opts.len();self.choice(actor,"jz42-time","末日钟降临：可移除本方牌上时间以减费".into(),opts,0,max,None,ChoiceResolution::JZ42Payment{draft:Box::new(d)});Ok(())}
 pub(crate) fn jz42_choose(&mut self,d:Draft,seat:usize,a:&Action,ids:&[String])->RuleResult<()>{self.jz42_draft(&d)?;if seat!=d.actor||*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")}){return Err("末日钟费用只能由原玩家确认".into())}self.apply_inner(seat,Action{card_id:Some(d.card.id),cost_selected:Some(ids.to_vec()),..Action::new("play")})}
 pub(crate) fn jz42_pay(&mut self,actor:usize,c:&Card,a:&Action)->RuleResult<Vec<PaidCost>>{action(a)?;let society=self.players[actor].society_zone.card.clone().ok_or("原秘社缺失")?;let d=Draft{actor,turn:self.turn,card:c.clone(),society:society.clone()};self.jz42_draft(&d)?;let ids=a.cost_selected.as_ref().ok_or("尚未选择时间支付")?;let opts=self.jz42_options(actor);if ids.iter().collect::<BTreeSet<_>>().len()!=ids.len()||ids.iter().any(|id|!opts.iter().any(|o|o.id==*id)){return Err("时间支付须为本方牌上不同的实际标志".into())}let before=self.effective_cost(actor,c);let mut removed=vec![];for card in self.jz42_carriers(actor){let n=ids.iter().filter(|id|id.starts_with(&format!("{}:",card.id))).count()as u32;if n>0{removed.push((card,n));}}let payment=self.capture_money(actor,before.saturating_sub(ids.len()as u32))?;let destroyed=self.regions.iter().filter(|r|!r.vacant&&r.destroyed).map(|r|r.card.id.clone()).collect();let used=self.modifiers.iter().enumerate().filter(|(_,m)|m.actor==actor&&m.uses>0&&m.expires_turn==self.turn&&self.filter_card(&m.filter,c)).map(|(i,_)|i).collect::<Vec<_>>();for i in used{self.modifiers[i].uses-=1;}for(card,n)in &removed{let live=self.ability_source_mut(&card.id).ok_or("时间支付原载体已离场")?;live.time_markers=live.time_markers.checked_sub(*n).ok_or("时间不足")?;}Ok(vec![payment,PaidCost::JZ42Time(Box::new(Payment{before,destroyed,society,removed}))])}
 pub(crate) fn jz42_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if f.source.card.definition!=ID&&f.ability_key!=KEY&&!f.steps.iter().any(|s|matches!(s.op,Op::JZ42Convert)){return Ok(())}self.validate_resource_frame(f)?;let [PaidCost::Assets(_),PaidCost::JZ42Time(p)]=f.already_paid.as_slice()else{return Err("末日钟降临缺原费用收据".into())};let n=p.removed.iter().try_fold(0u32,|n,(_,x)|n.checked_add(*x)).ok_or("时间支付溢出")?;let c=&f.source.card;if c.definition!=ID||c.face_down||f.actor>=self.players.len()||c.controller!=f.actor||c.owner>=self.players.len()||!self.mystic_instance_valid(&c.id)||!self.mystic_instance_valid(&f.frame_id)||f.frame_id==c.id||f.source.death_echo.is_some()||f.source.observed_death.is_some()||f.source.observed_exposure.is_some()||f.source.observed_mobility_grant.is_some()||f.source.attachment_host_instance.is_some()||f.ability_key!=KEY||f.source.region.is_some()||f.source.source_region_instance.is_some()||f.source.play_source.is_some()||f.cursor>1||!f.targets.is_empty()||f.chosen_region.is_some()||!same(&f.steps,&vec![Step{context:f.actor,op:Op::JZ42Convert}])||p.before>19u32.saturating_sub((p.destroyed.len()as u32).saturating_mul(4))||p.destroyed.iter().collect::<BTreeSet<_>>().len()!=p.destroyed.len()||f.money_units(0)!=p.before.saturating_sub(n)as usize||p.society.controller!=f.actor||p.society.owner!=f.actor||p.society.face_down||!catalog::catalog().societies.iter().any(|s|s.card.id==p.society.definition)||p.removed.iter().map(|(c,_)|&c.id).collect::<BTreeSet<_>>().len()!=p.removed.len()||p.removed.iter().any(|(c,n)|*n==0||*n>c.time_markers||c.controller!=f.actor||!self.mystic_instance_valid(&c.id))||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted){return Err("末日钟降临原来源、减免或阶段损坏".into())}self.mobility_immutable_identity(c)?;for(c,_)in &p.removed{self.mobility_immutable_identity(c)?;}Ok(())}
 pub(crate) fn jz42_convert(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.jz42_frame(f)?;if f.cursor!=1{return Err("末日钟转换须消费原步骤".into())}let PaidCost::JZ42Time(p)=&f.already_paid[1]else{unreachable!()};let c=self.players[f.actor].society_zone.card.as_mut().ok_or("原秘社缺失")?;if c.id!=p.society.id||c.definition!=p.society.definition{return Err("末日钟不能替换另一秘社实体".into())}c.definition=crate::msjz03::ID.into();self.check_win();Ok(())}
 pub(crate) fn validate_jz42_state(&self)->RuleResult<()>{for i in &self.stack{if i.card.as_ref().is_some_and(|c|c.definition==ID)||i.frame.as_ref().is_some_and(|f|f.source.card.definition==ID||f.ability_key==KEY){return Err("末日钟降临不能留在可响应堆叠".into())}}let mut ids=BTreeSet::new();for e in &self.effects{if let Effect::Frame{frame:f}=e{self.jz42_frame(f)?;if f.ability_key==KEY&&!ids.insert(&f.frame_id){return Err("末日钟转换重复续体".into())}}}if let Some(p)=&self.pending{if let ChoiceResolution::JZ42Payment{draft:d}=&p.resolution{self.jz42_draft(d)?;let opts=self.jz42_options(d.actor);let expected=Choice{id:p.choice.id.clone(),kind:"jz42-time".into(),title:"末日钟降临：可移除本方牌上时间以减费".into(),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(d.actor),min:Some(0),max:Some(opts.len()),options:opts,preview_cards:vec![],amount:None,allow_decline:Some(true)};if p.seat!=d.actor||!self.mystic_instance_valid(&p.choice.id)||!same(&p.choice,&expected){return Err("末日钟费用待选损坏".into())}}}Ok(())}
}
